/* =============================================================================
 * Condo Market SF - Supabase Client (cm-supabase.js)
 * -----------------------------------------------------------------------------
 * Drop-in ESM module. Loads the Supabase v2 client from CDN and exposes a
 * small, stable API used by the auth modal and future feature modules
 * (offers, Make-Me-Move, dashboards).
 *
 * Config (URL + anon key) is imported from cm-config.js — that's the ONLY
 * file you paste the anon key into. Do not edit this file.
 *
 * Usage in any HTML page:
 *   <script type="module">
 *     import { CM } from '/assets/cm-supabase.js';
 *     const user = await CM.getUser();
 *   </script>
 * ========================================================================== */

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { SUPABASE_URL, SUPABASE_ANON_KEY } from './cm-config.js';

// ---- Client singleton ----------------------------------------------------
export const sb = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
  auth: {
    persistSession:     true,
    autoRefreshToken:   true,
    detectSessionInUrl: true,
    storageKey:         'cm-auth-session',
  },
});

// ---- Auth redirect URL helpers -------------------------------------------
//
// Every sign-up / magic-link flow uses the same dedicated callback page so
// Supabase always has a single, known-good redirect target. The callback
// page reads the return path from localStorage and sends the user there.
const AUTH_CALLBACK_PATH = '/auth-callback.html';
const RETURN_STORAGE_KEY = 'cm_return_to';

/**
 * Build the absolute URL Supabase should redirect to after email confirmation
 * or magic-link click. Always points at the auth callback page on this origin.
 */
function buildAuthCallbackUrl() {
  return window.location.origin + AUTH_CALLBACK_PATH;
}

/**
 * Remember where the user was when they initiated sign-up / sign-in, so the
 * callback page can send them back there after the email link is clicked.
 * Skips storing the callback page itself (avoids redirect loops).
 */
function rememberCurrentPath() {
  try {
    const path = window.location.pathname + window.location.search;
    if (path.indexOf(AUTH_CALLBACK_PATH) !== -1) return;
    if (path === '/' || path === '') {
      localStorage.setItem(RETURN_STORAGE_KEY, '/buildings/');
    } else {
      localStorage.setItem(RETURN_STORAGE_KEY, path);
    }
  } catch (e) {
    // localStorage may be unavailable (private browsing); fail silently.
  }
}

// ---- Referral attribution (capture ?ref=CODE from URL) -------------------
const REF_STORAGE_KEY = 'cm_referral_code';
const REF_EXPIRY_DAYS = 30;

/**
 * Reads ?ref= from the URL on page load, stores it in localStorage with
 * a 30-day expiry. Called automatically on module init below.
 */
function captureReferralFromUrl() {
  try {
    const url = new URL(window.location.href);
    const ref = url.searchParams.get('ref');
    if (!ref) return;

    const clean = String(ref).trim().toUpperCase().slice(0, 12);
    if (!clean) return;

    const payload = {
      code: clean,
      expires_at: Date.now() + REF_EXPIRY_DAYS * 24 * 60 * 60 * 1000,
    };
    localStorage.setItem(REF_STORAGE_KEY, JSON.stringify(payload));
  } catch (e) {
    // localStorage may be unavailable (private browsing); fail silently.
  }
}

/**
 * Returns the stored referral code if still valid, else null.
 */
export function getStoredReferralCode() {
  try {
    const raw = localStorage.getItem(REF_STORAGE_KEY);
    if (!raw) return null;
    const { code, expires_at } = JSON.parse(raw);
    if (!code || !expires_at || Date.now() > expires_at) {
      localStorage.removeItem(REF_STORAGE_KEY);
      return null;
    }
    return code;
  } catch (e) {
    return null;
  }
}

/**
 * Clear the stored referral code (call after successful signup).
 */
export function clearStoredReferralCode() {
  try { localStorage.removeItem(REF_STORAGE_KEY); } catch (e) {}
}

/**
 * Ask Supabase who the referrer is behind a given code, returning a
 * friendly name string or null.
 */
export async function resolveReferrerName(code) {
  if (!code) return null;
  const { data, error } = await sb.rpc('get_referrer_name', { code });
  if (error) {
    console.warn('[cm] get_referrer_name failed:', error.message);
    return null;
  }
  return data || null;
}

// Auto-capture on module init
captureReferralFromUrl();

// ---- Auth API wrapper ----------------------------------------------------
export const CM = {
  /** Get the current session user (or null). */
  async getUser() {
    const { data: { user } } = await sb.auth.getUser();
    return user;
  },

  /** Get current session (access token etc) or null. */
  async getSession() {
    const { data: { session } } = await sb.auth.getSession();
    return session;
  },

  /** Sign up with email + password. Passes full_name, phone, and stored ref code into raw_user_meta_data. */
  async signUp({ email, password, fullName, phone }) {
    rememberCurrentPath();
    const referralCode = getStoredReferralCode();
    const { data, error } = await sb.auth.signUp({
      email,
      password,
      options: {
        emailRedirectTo: buildAuthCallbackUrl(),
        data: {
          full_name: fullName || '',
          phone: phone || '',
          referred_by_code: referralCode || '',
        },
      },
    });
    if (!error) clearStoredReferralCode();
    return { data, error };
  },

  /** Sign in with email + password. */
  async signIn({ email, password }) {
    return await sb.auth.signInWithPassword({ email, password });
  },

  /** Send a magic link. */
  async sendMagicLink({ email }) {
    rememberCurrentPath();
    const referralCode = getStoredReferralCode();
    return await sb.auth.signInWithOtp({
      email,
      options: {
        emailRedirectTo: buildAuthCallbackUrl(),
        data: { referred_by_code: referralCode || '' },
      },
    });
  },

  /** Sign out. */
  async signOut() {
    return await sb.auth.signOut();
  },

  /** Subscribe to auth state changes (returns an unsubscribe function). */
  onAuthChange(callback) {
    const { data: { subscription } } = sb.auth.onAuthStateChange(
      (event, session) => callback(event, session)
    );
    return () => subscription.unsubscribe();
  },

  /** Fetch the current user's profile row (or null). */
  async getMyProfile() {
    const user = await this.getUser();
    if (!user) return null;
    const { data, error } = await sb
      .from('profiles')
      .select('*')
      .eq('id', user.id)
      .maybeSingle();
    if (error) {
      console.warn('[cm] getMyProfile failed:', error.message);
      return null;
    }
    return data;
  },

  /** Update the current user's editable profile fields (name, phone only). */
  async updateMyProfile({ full_name, phone }) {
    const user = await this.getUser();
    if (!user) return { error: new Error('not signed in') };
    return await sb
      .from('profiles')
      .update({ full_name, phone })
      .eq('id', user.id)
      .select()
      .single();
  },

  /** Build a shareable ?ref=<code> URL for the current user. */
  async buildReferralLink(basePath = '/') {
    const profile = await this.getMyProfile();
    if (!profile || !profile.referral_code) return null;
    const url = new URL(basePath, window.location.origin);
    url.searchParams.set('ref', profile.referral_code);
    return url.toString();
  },

  /** List referral credits for the current user (as referrer). */
  async listMyReferralCredits() {
    const user = await this.getUser();
    if (!user) return [];
    const { data, error } = await sb
      .from('referral_credits')
      .select('*')
      .eq('referrer_id', user.id)
      .order('awarded_at', { ascending: false });
    if (error) {
      console.warn('[cm] listMyReferralCredits failed:', error.message);
      return [];
    }
    return data || [];
  },

  // ---------------------------------------------------------------------------
  // Make-Me-Move listings
  // ---------------------------------------------------------------------------

  /**
   * Insert a new make-me-move listing for the current user.
   * Required: address, price. Optional: unit_number, building, city, beds, baths, sqft, notes.
   * Returns { data, error }.
   */
  async setMakeMyMove({ address, unit_number, building, city, beds, baths, sqft, price, notes } = {}) {
    const user = await this.getUser();
    if (!user) return { data: null, error: new Error('not signed in') };
    if (!address || !price) return { data: null, error: new Error('address and price are required') };
    return await sb
      .from('listings')
      .insert({
        user_id:     user.id,
        address:     address,
        unit_number: unit_number || null,
        building:    building || null,
        city:        city || 'San Francisco',
        beds:        beds || null,
        baths:       baths || null,
        sqft:        sqft || null,
        price:       Math.round(price),
        notes:       notes || null,
        status:      'active',
      })
      .select()
      .single();
  },

  /** Get all listings owned by the current user, newest first. */
  async getMyListings() {
    const user = await this.getUser();
    if (!user) return [];
    const { data, error } = await sb
      .from('listings')
      .select('*')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false });
    if (error) {
      console.warn('[cm] getMyListings failed:', error.message);
      return [];
    }
    return data || [];
  },

  /**
   * Get all ACTIVE listings for a given building. Members-only via RLS.
   * Used by building pages to display make-me-move prices to signed-in buyers.
   */
  async getActiveListingsForBuilding(buildingSlug) {
    if (!buildingSlug) return [];
    const { data, error } = await sb
      .from('listings')
      .select('id, address, unit_number, building, beds, baths, sqft, price, orientation, cover_photo_path, additional_photo_paths, created_at')
      .eq('building', buildingSlug)
      .eq('status', 'active')
      .order('created_at', { ascending: false });
    if (error) {
      console.warn('[cm] getActiveListingsForBuilding failed:', error.message);
      return [];
    }
    return data || [];
  },

  /**
   * Update fields on a listing the current user owns. RLS enforces ownership.
   * Common updates: { price }, { status: 'paused' | 'active' | 'sold' | 'removed' }, { unit_number }, { sqft }.
   */
  async updateListing(id, updates) {
    if (!id) return { data: null, error: new Error('id required') };
    const user = await this.getUser();
    if (!user) return { data: null, error: new Error('not signed in') };
    return await sb
      .from('listings')
      .update(updates)
      .eq('id', id)
      .eq('user_id', user.id)
      .select()
      .single();
  },

  /** Convenience: pause an active listing. */
  async pauseListing(id)  { return await this.updateListing(id, { status: 'paused' }); },

  /** Convenience: resume a paused listing. */
  async resumeListing(id) { return await this.updateListing(id, { status: 'active' }); },

  /** Convenience: soft-remove a listing (set status=removed). */
  async removeListing(id) { return await this.updateListing(id, { status: 'removed' }); },

  // ---------------------------------------------------------------------------
  // Unit claims (user_units) — Sprint B-2D dashboard gate
  // ---------------------------------------------------------------------------
  //
  // The listings_require_approved_claim_trg trigger rejects any INSERT into
  // public.listings unless an approved user_units row exists for the SAME
  // user_id + building_slug + (normalized) unit. The dashboard reads claim
  // status via this method so it can surface a gating UI before the user
  // attempts an insert that the DB will block.

  /**
   * Return all unit-ownership claims for the current user across statuses
   * (pending / approved / rejected), newest first. RLS allows users to read
   * only their own user_units rows.
   */
  async getMyUnitClaims() {
    const user = await this.getUser();
    if (!user) return [];
    const { data, error } = await sb
      .from('user_units')
      .select('id, building_slug, unit_address, claimed_name, status, reviewed_at, created_at')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false });
    if (error) {
      console.warn('[cm] getMyUnitClaims failed:', error.message);
      return [];
    }
    return data || [];
  },

  // ---------------------------------------------------------------------------
  // Offers — buyer submits, owner & admin see, status transitions accept/decline/withdraw
  // ---------------------------------------------------------------------------

  /**
   * Get a single listing by id for offer-modal context.
   * RLS: buyer must be authenticated AND the listing must be active.
   */
  async getListingById(id) {
    if (!id) return null;
    const { data, error } = await sb
      .from('listings')
      .select('id, address, unit_number, building, sqft, beds, baths, price, status, cover_photo_path, additional_photo_paths, floorplan_path, orientation')
      .eq('id', id)
      .maybeSingle();
    if (error) {
      console.warn('[cm] getListingById failed:', error.message);
      return null;
    }
    return data;
  },

  /**
   * Create an offer. Required: building_slug, offer_amount.
   * Optional: listing_id (when offer is on a specific MMM unit), message.
   * Returns { data, error }.
   */
  async createOffer({ listing_id, building_slug, offer_amount, message } = {}) {
    const user = await this.getUser();
    if (!user) return { data: null, error: new Error('not signed in') };
    if (!building_slug)              return { data: null, error: new Error('building_slug required') };
    if (!offer_amount || offer_amount <= 0) return { data: null, error: new Error('valid offer_amount required') };

    // Buyer name from profile (fallback to user_metadata)
    let buyerName = user.user_metadata?.full_name || null;
    try {
      const profile = await this.getMyProfile();
      if (profile?.full_name) buyerName = profile.full_name;
    } catch (e) { /* profile optional */ }

    return await sb
      .from('offers')
      .insert({
        listing_id:    listing_id || null,
        building_slug: building_slug,
        buyer_user_id: user.id,
        buyer_email:   user.email,
        buyer_name:    buyerName,
        offer_amount:  Math.round(offer_amount),
        message:       message || null,
      })
      .select()
      .single();
  },

  /** Get all offers the current user has submitted (buyer view), newest first. Embeds rounds for thread display. */
  async listMyOffers() {
    const user = await this.getUser();
    if (!user) return [];
    const { data, error } = await sb
      .from('offers')
      .select('*, rounds:offer_rounds(round_number, amount, message, from_role, created_at)')
      .eq('buyer_user_id', user.id)
      .order('created_at', { ascending: false });
    if (error) {
      console.warn('[cm] listMyOffers failed:', error.message);
      return [];
    }
    return data || [];
  },

  /**
   * Get all offers received on the current user's MMM listings (owner view).
   * RLS lets owner see only their own listings' offers; we re-fetch the
   * listings to attach address/price context per offer for rendering.
   */
  async listOffersForMyListings() {
    const user = await this.getUser();
    if (!user) return [];
    const { data: offers, error } = await sb
      .from('offers')
      .select('*, rounds:offer_rounds(round_number, amount, message, from_role, created_at)')
      .not('listing_id', 'is', null)
      .order('created_at', { ascending: false });
    if (error) {
      console.warn('[cm] listOffersForMyListings failed:', error.message);
      return [];
    }
    if (!offers || offers.length === 0) return [];
    const listingIds = [...new Set(offers.map(o => o.listing_id).filter(Boolean))];
    const { data: listings } = await sb
      .from('listings')
      .select('id, address, unit_number, building, price, cover_photo_path')
      .in('id', listingIds);
    const listingMap = {};
    (listings || []).forEach(l => { listingMap[l.id] = l; });
    return offers.map(o => ({ ...o, listing: listingMap[o.listing_id] || null }));
  },

  /** Admin-only: get all offers across the platform. RLS gates this. */
  async listAllOffers() {
    const { data, error } = await sb
      .from('offers')
      .select('*')
      .order('created_at', { ascending: false });
    if (error) {
      console.warn('[cm] listAllOffers failed:', error.message);
      return [];
    }
    return data || [];
  },

  /** Update an offer's status. RLS gates which transitions a user can make. */
  async updateOfferStatus(id, status) {
    if (!id) return { data: null, error: new Error('id required') };
    if (!['pending','accepted','declined','expired','withdrawn'].includes(status)) {
      return { data: null, error: new Error('invalid status: ' + status) };
    }
    return await sb
      .from('offers')
      .update({ status })
      .eq('id', id)
      .select()
      .single();
  },

  async withdrawOffer(id) { return await this.updateOfferStatus(id, 'withdrawn'); },
  async acceptOffer(id)   { return await this.updateOfferStatus(id, 'accepted'); },
  async declineOffer(id)  { return await this.updateOfferStatus(id, 'declined'); },

  // ---------------------------------------------------------------------------
  // Counter-offer workflow (v19)
  // ---------------------------------------------------------------------------

  /**
   * Counter an offer. Calls the counter_offer() RPC which atomically:
   *   - Validates the user's role on the offer (buyer or owner)
   *   - Validates it's their turn (awaiting_response_from matches role)
   *   - Inserts a new offer_rounds row
   *   - Updates offers: status='countered', current_round++, awaiting flips
   *
   * Used by both buyer (countering an owner counter) and owner (countering an
   * initial offer or buyer counter-back). The DB trigger fires
   * `offer_countered` event → email goes to the OTHER party.
   *
   * @param {string} offerId
   * @param {number} amount  - the counter amount in dollars
   * @param {string} [message] - optional message to accompany the counter
   * @returns {{ data: offer|null, error: Error|null }}
   */
  async counterOffer(offerId, amount, message) {
    if (!offerId)            return { data: null, error: new Error('offerId required') };
    if (!amount || amount <= 0) return { data: null, error: new Error('amount must be > 0') };
    const { data, error } = await sb.rpc('counter_offer', {
      p_offer_id: offerId,
      p_amount:   Math.round(Number(amount)),
      p_message:  message ? String(message).trim() : null,
    });
    return { data, error };
  },

  /**
   * Get the full round history for an offer, in chronological order.
   * Round 1 is always the buyer's initial; subsequent rounds alternate.
   * Visible to: buyer, owner, admin (RLS enforced).
   */
  async getOfferRounds(offerId) {
    if (!offerId) return [];
    const { data, error } = await sb
      .from('offer_rounds')
      .select('*')
      .eq('offer_id', offerId)
      .order('round_number', { ascending: true });
    if (error) {
      console.warn('[cm] getOfferRounds failed:', error.message);
      return [];
    }
    return data || [];
  },

  // ---------------------------------------------------------------------------
  // TOS acceptance — record that the current user has accepted a given
  // version of the platform Terms of Service.
  // ---------------------------------------------------------------------------
  async acceptTos(version) {
    const user = await this.getUser();
    if (!user) return { data: null, error: new Error('not signed in') };
    return await sb
      .from('profiles')
      .update({ tos_accepted_at: new Date().toISOString(), tos_version: version })
      .eq('id', user.id)
      .select()
      .single();
  },

  // ---------------------------------------------------------------------------
  // Listing photos — upload to Supabase Storage, save path on listings row.
  // Path convention: {user_id}/{listing_id}/{uuid}.jpg
  // RLS: bucket is public-read, owner-scoped write (folder #1 = auth.uid()).
  // ---------------------------------------------------------------------------

  /**
   * Construct the public CDN URL for a stored listing photo path.
   * Returns null if path is null. Uses the storage public-URL helper.
   */
  getListingPhotoUrl(path) {
    if (!path) return null;
    const { data } = sb.storage.from('listing-photos').getPublicUrl(path);
    return data?.publicUrl || null;
  },

  /**
   * Upload a photo file for a listing. Resizes client-side to max 1600px wide
   * before upload to keep payloads small. Replaces any existing photo.
   * Returns { data: { path, publicUrl }, error }.
   */
  async uploadListingPhoto(listingId, file) {
    const user = await this.getUser();
    if (!user)             return { data: null, error: new Error('not signed in') };
    if (!listingId || !file) return { data: null, error: new Error('listingId and file required') };
    if (!file.type?.startsWith('image/')) return { data: null, error: new Error('file must be an image') };

    // Resize via canvas to max 1600px wide (preserves aspect ratio, jpeg @ 0.85)
    const resizedBlob = await this._resizeImage(file, 1600, 0.85);

    // Look up existing path so we can clean it up afterward
    const { data: existing } = await sb.from('listings')
      .select('cover_photo_path').eq('id', listingId).maybeSingle();
    const oldPath = existing?.cover_photo_path || null;

    // Generate fresh path so cached old URLs don't ghost the new image
    const uuid = (typeof crypto !== 'undefined' && crypto.randomUUID)
      ? crypto.randomUUID()
      : (Date.now() + '-' + Math.random().toString(16).slice(2));
    const newPath = `${user.id}/${listingId}/${uuid}.jpg`;

    // Upload (RLS allows since the first folder = auth.uid())
    const { error: uploadErr } = await sb.storage
      .from('listing-photos')
      .upload(newPath, resizedBlob, {
        contentType: 'image/jpeg',
        cacheControl: '604800',  // 1 week
        upsert: false,
      });
    if (uploadErr) return { data: null, error: uploadErr };

    // Update the listing row to point at the new path
    const { error: updateErr } = await this.updateListing(listingId, { cover_photo_path: newPath });
    if (updateErr) {
      // Best-effort: clean up the uploaded file since the listing didn't get linked
      await sb.storage.from('listing-photos').remove([newPath]).catch(() => {});
      return { data: null, error: updateErr };
    }

    // Clean up the old file (best-effort; failure here is fine, just leaves an orphan)
    if (oldPath && oldPath !== newPath) {
      await sb.storage.from('listing-photos').remove([oldPath]).catch(() => {});
    }

    const publicUrl = this.getListingPhotoUrl(newPath);
    return { data: { path: newPath, publicUrl }, error: null };
  },

  /**
   * Remove the cover photo from a listing: delete from storage AND null out the column.
   */
  async removeListingPhoto(listingId) {
    if (!listingId) return { error: new Error('listingId required') };
    const { data: existing } = await sb.from('listings')
      .select('cover_photo_path').eq('id', listingId).maybeSingle();
    const path = existing?.cover_photo_path || null;

    const { error: updateErr } = await this.updateListing(listingId, { cover_photo_path: null });
    if (updateErr) return { error: updateErr };

    if (path) {
      await sb.storage.from('listing-photos').remove([path]).catch(() => {});
    }
    return { error: null };
  },

  /**
   * Internal helper: resize an image File via a canvas, returning a Blob.
   * Preserves aspect ratio, caps the LONGER edge at maxLongEdge px.
   */
  async _resizeImage(file, maxLongEdge = 1600, quality = 0.85) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          const longEdge = Math.max(img.width, img.height);
          const scale = longEdge > maxLongEdge ? maxLongEdge / longEdge : 1;
          const w = Math.round(img.width * scale);
          const h = Math.round(img.height * scale);
          const canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, w, h);
          canvas.toBlob(
            (blob) => blob ? resolve(blob) : reject(new Error('canvas toBlob failed')),
            'image/jpeg',
            quality,
          );
        };
        img.onerror = () => reject(new Error('image load failed'));
        img.src = e.target.result;
      };
      reader.onerror = () => reject(new Error('file read failed'));
      reader.readAsDataURL(file);
    });
  },

  /** Low-level: expose the raw client for advanced use. */
  client: sb,

  /** Low-level: referral utilities. */
  referral: {
    getStored: getStoredReferralCode,
    clear:     clearStoredReferralCode,
    resolve:   resolveReferrerName,
  },

  // ---- Watchlist (v21) -----------------------------------------------------
  async addToWatchlist(buildingSlug) {
    const { data: { user } } = await sb.auth.getUser();
    if (!user) return { error: { message: 'Not signed in' } };
    if (!buildingSlug) return { error: { message: 'Missing slug' } };
    const { data, error } = await sb.from('watchlist')
      .upsert({ user_id: user.id, building_slug: buildingSlug },
              { onConflict: 'user_id,building_slug', ignoreDuplicates: true })
      .select().maybeSingle();
    return { data, error };
  },
  async removeFromWatchlist(buildingSlug) {
    const { data: { user } } = await sb.auth.getUser();
    if (!user) return { error: { message: 'Not signed in' } };
    const { error } = await sb.from('watchlist')
      .delete().eq('user_id', user.id).eq('building_slug', buildingSlug);
    return { error };
  },
  async listMyWatchlist() {
    const { data: { user } } = await sb.auth.getUser();
    if (!user) return [];
    const { data, error } = await sb.from('watchlist')
      .select('id, building_slug, created_at')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false });
    return error ? [] : (data || []);
  },
  async isInMyWatchlist(buildingSlug) {
    if (!buildingSlug) return false;
    const { data: { user } } = await sb.auth.getUser();
    if (!user) return false;
    const { data, error } = await sb.from('watchlist')
      .select('id').eq('user_id', user.id)
      .eq('building_slug', buildingSlug).maybeSingle();
    return !error && !!data;
  },
};

// ---- Per-pageload request de-duplication (v22) ----------------------------
//
// The dashboard runs two independent inline modules (render + shell). Neither
// knows the other exists, so a single page load was firing getSession twice,
// getMyProfile twice, getMyListings up to five times and listOffersForMyListings
// three times -- a dozen serialised round trips where four would do. That is
// what produced the long "Loading your dashboard..." pause.
//
// This caches the IN-FLIGHT PROMISE, not the result. The first caller issues the
// query; every later caller within the same pageload awaits the same promise.
// There is no staleness window to reason about because the cache dies on
// navigation, and any mutation clears it explicitly below.
//
// Call sites are unchanged -- every existing CM.x() keeps working exactly as
// before, it just may resolve from a promise someone else started.

const _cmInflight = new Map();

/** Drop cached reads. Pass a prefix to clear a subset, or nothing to clear all. */
function cmInvalidate(prefix) {
  if (!prefix) { _cmInflight.clear(); return; }
  for (const k of Array.from(_cmInflight.keys())) {
    if (k.startsWith(prefix)) _cmInflight.delete(k);
  }
}

function _cmMemoize(name) {
  const orig = CM[name];
  if (typeof orig !== 'function') return;
  CM[name] = function (...args) {
    let key;
    try { key = name + ':' + JSON.stringify(args); } catch (e) { key = null; }
    // Unserialisable args (rare) bypass the cache rather than collide.
    if (key === null) return orig.apply(CM, args);
    if (_cmInflight.has(key)) return _cmInflight.get(key);
    const p = Promise.resolve()
      .then(() => orig.apply(CM, args))
      // A failed read must not be cached, or one blip poisons the whole pageload.
      .catch((err) => { _cmInflight.delete(key); throw err; });
    _cmInflight.set(key, p);
    return p;
  };
}

// Idempotent reads only. getUser is first so that getMyProfile's internal
// this.getUser() call resolves against the memoised version.
[
  'getUser',
  'getSession',
  'getMyProfile',
  'getMyListings',
  'getMyUnitClaims',
  'listMyOffers',
  'listOffersForMyListings',
].forEach(_cmMemoize);

// Writes invalidate. Anything that changes listings, offers, profile or auth
// state clears the cache so a subsequent read re-queries.
function _cmInvalidateAfter(name, prefix) {
  const orig = CM[name];
  if (typeof orig !== 'function') return;
  CM[name] = async function (...args) {
    const out = await orig.apply(CM, args);
    cmInvalidate(prefix);
    return out;
  };
}

[
  ['setMakeMyMove',      null],
  ['updateListing',      null],
  ['pauseListing',       null],
  ['resumeListing',      null],
  ['removeListing',      null],
  ['removeListingPhoto', null],
  ['updateOfferStatus',  null],
  ['withdrawOffer',      null],
  ['acceptOffer',        null],
  ['declineOffer',       null],
  ['addToWatchlist',     null],
  ['signIn',             null],
  ['signOut',            null],
  ['signUp',             null],
].forEach(([n, p]) => _cmInvalidateAfter(n, p));

// Exposed so a page can force a refetch after an out-of-band change.
CM.invalidate = cmInvalidate;

// Auth transitions must never serve a previous user's cached rows.
try {
  sb.auth.onAuthStateChange(() => { cmInvalidate(); });
} catch (e) { /* non-fatal: cache still clears on navigation and on writes */ }

// ---- Default export for convenience --------------------------------------
export default CM;
